import {nyTime,displayTime,buildIndex,findMoment,rankCandidates,priorDate} from './core.js';
const $=id=>document.getElementById(id);
let index=new Map(), current=null, preview=null, activeKey='', generation=0, loading=false, photos=[];
const failed=new Set();
function note(message=''){$('network-note').textContent=message;$('network-note').hidden=!message;}
function safeHref(el,url){if(/^https:\/\//.test(url||''))el.href=url;else el.removeAttribute('href');}
function clockState(){const real=nyTime();return preview===null?real:{...real,minute:preview,second:0};}
function updateClock(){const state=clockState(), t=displayTime(state.minute);$('clock').textContent=t.clock;$('period').textContent=t.period;$('seconds').textContent=preview===null?':'+String(state.second).padStart(2,'0'):'—';$('clock').setAttribute('aria-label',`${preview===null?'Current':'Exploring'} New York time ${t.clock} ${t.period}`);$('mode').replaceChildren();if(preview===null){const dot=document.createElement('i');dot.className='live-dot';dot.setAttribute('aria-hidden','true');$('mode').append(dot);}$('mode').append(document.createTextNode(preview===null?'LIVE FROM NEW YORK':'EXPLORING THE DAY'));$('calendar').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric'}).format(new Date()).toUpperCase();$('zone').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',timeZoneName:'short'}).formatToParts(new Date()).find(x=>x.type==='timeZoneName').value+' · NEW YORK, NY';updateMatch(state);return state;}
function updateMatch(state){if(!current)return;const lag=(state.minute-current.minute+1440)%1440;const t=displayTime(current.minute);$('match-status').textContent=lag===0?'A photograph recorded at this minute.':`Holding the ${t.clock} ${t.period.toLowerCase()} photograph.`;}
function loadImage(url){return new Promise((resolve,reject)=>{const img=new Image();const timeout=setTimeout(()=>{img.onload=img.onerror=null;reject(new Error('Image timed out'));},10000);img.onload=()=>{clearTimeout(timeout);resolve(img);};img.onerror=()=>{clearTimeout(timeout);reject(new Error('Image unavailable'));};img.referrerPolicy='no-referrer';img.src=url;});}
function showPhoto(photo,img){const element=$('photo');element.src=img.src;element.alt=(photo.description||photo.title.replace(/^File:/,'')).slice(0,700);element.hidden=false;$('image-placeholder').hidden=true;$('retry').hidden=true;current=photo;const t=displayTime(photo.minute);$('capture-time').textContent=`${t.clock} ${t.period.toLowerCase()}`;$('capture-date').textContent=new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(photo.capture_date+'T12:00:00Z'));$('photo-title').textContent=photo.title.replace(/^File:/,'').replace(/\.(jpe?g|png|webp|tiff?)$/i,'').replaceAll('_',' ');safeHref($('photo-title'),photo.source_url);safeHref($('source'),photo.source_url);$('photo-credit').textContent=[photo.attribution,photo.artist&&(!photo.attribution||!photo.attribution.includes(photo.artist))?photo.artist:'',photo.credit&&photo.credit!=='Own work'&&photo.credit!==photo.artist?photo.credit:''].filter(Boolean).join(' · ');$('license').textContent=photo.license;safeHref($('license'),photo.license_url||photo.source_url);$('location').textContent=photo.borough?'Photographed in '+photo.borough:'An NYC scene';$('time-evidence').textContent=photo.timezone_status==='explicit_offset'?'Capture time includes a recorded time-zone offset.':'Camera time; assumed local to New York.';updateMatch(clockState());}
async function refresh(force=false){if(!index.size)return;const state=updateClock(),moment=findMoment(index,state.minute,state.date);if(!moment)return;const key=`${moment.date}|${moment.minute}`;if(!force&&key===activeKey)return;activeKey=key;const token=++generation;loading=true;$('stage').setAttribute('aria-busy','true');let choices=rankCandidates(moment.photos,moment.date,moment.minute);
  // If a file disappears, first try this minute's alternatives, then earlier moments.
  let cursor=moment.minute-1, day=moment.date, seen=new Set(choices.map(p=>p.pageid));
  while(choices.length<8){if(cursor<0){day=priorDate(day);cursor=1439;}const previous=findMoment(index,cursor,day);if(!previous)break;const additions=rankCandidates(previous.photos,previous.date,previous.minute).filter(p=>!seen.has(p.pageid));if(!additions.length)break;choices.push(...additions);additions.forEach(p=>seen.add(p.pageid));cursor=previous.minute-1;day=previous.date;}
  let attempts=0;
  for(const photo of choices){if(token!==generation)return;if(failed.has(photo.pageid))continue;if(++attempts>5)break;try{const img=await loadImage(photo.thumbnail_url);if(token!==generation)return;showPhoto(photo,img);note(photo.minute===moment.minute?'':'The closest photograph could not load, so an earlier available moment is shown.');loading=false;$('stage').setAttribute('aria-busy','false');return;}catch{failed.add(photo.pageid);}}
  if(token!==generation)return;loading=false;$('stage').setAttribute('aria-busy','false');note(current?'Some Wikimedia images are temporarily unavailable. Keeping the current photograph.':'Wikimedia images are temporarily unavailable. The clock is still running; you can try again.');$('retry').hidden=false;if(!current){$('image-placeholder').replaceChildren(Object.assign(document.createElement('p'),{textContent:'The city is taking a moment.'}));$('match-status').textContent='Photographs temporarily unavailable.';}
}
async function init(){updateClock();try{const response=await fetch('./photos.json');if(!response.ok)throw new Error('Collection unavailable');const data=await response.json();photos=data.photos;index=buildIndex(photos);if(!index.size)throw new Error('Empty collection');$('collection-description').textContent=`This first edition includes ${photos.length} provisional photographs covering ${index.size} distinct minutes, discovered through geographic searches, categories, article images, and place names on Wikimedia Commons.`;await refresh();}catch{note('The photograph collection could not load. Please reload the page to try again.');$('match-status').textContent='Collection unavailable.';$('stage').setAttribute('aria-busy','false');$('image-placeholder').textContent='The city is taking a moment.';}}
setInterval(()=>{updateClock();if(!loading)refresh();},1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){activeKey='';refresh();}});
window.addEventListener('online',()=>{failed.clear();refresh(true);});
$('retry').addEventListener('click',()=>{failed.clear();refresh(true);});
$('explore-button').addEventListener('click',()=>{const opening=$('explorer').hidden;$('explorer').hidden=!opening;$('explore-button').setAttribute('aria-expanded',String(opening));$('explore-button').lastElementChild.textContent=opening?'−':'＋';if(opening){const m=clockState().minute;$('time-input').value=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');$('time-input').focus();}});
$('time-form').addEventListener('submit',event=>{event.preventDefault();const [h,m]=$('time-input').value.split(':').map(Number);if(Number.isInteger(h)&&Number.isInteger(m)&&h<24&&m<60){preview=h*60+m;activeKey='';updateClock();refresh();}});
$('live-button').addEventListener('click',()=>{preview=null;activeKey='';updateClock();refresh();});
for(const id of ['about-button','collection-button'])$(id).addEventListener('click',()=>$('about-dialog').showModal());
$('close-about').addEventListener('click',()=>$('about-dialog').close());
$('about-dialog').addEventListener('click',event=>{if(event.target===$('about-dialog')){const r=$('about-dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('about-dialog').close();}});
init();
